FUNCTION_BLOCK FB_P13
VAR_INPUT
    OCCUPANCY_DETECTED : BOOL;
    ENERGY_SAVING_MODE : BOOL;
    HVAC_MODE_SELECTOR : INT;
END_VAR
VAR_OUTPUT
    SUPPLY_FAN_RUN : BOOL := FALSE;
    TEMP_SETPOINT_ADJUST : INT := 0;
END_VAR
VAR
    Initialized : BOOL := FALSE;
    StartDelayScans : INT := 0;
END_VAR

(* First invocation is the power-up scan required by C10.
   Normal calculation starts on the following invocation.
   Each normal invocation represents one 20 ms scan;
   1500 consecutive permitted scans represent 30 seconds. *)
IF NOT Initialized THEN
    SUPPLY_FAN_RUN := FALSE;
    TEMP_SETPOINT_ADJUST := 0;
    StartDelayScans := 0;
    Initialized := TRUE;
ELSE
    (* Loss of permission stops the fan and resets the delay
       within the current scan. *)
    IF OCCUPANCY_DETECTED AND (HVAC_MODE_SELECTOR <> 3) THEN
        IF StartDelayScans < 1500 THEN
            StartDelayScans := StartDelayScans + 1;
        END_IF;
        SUPPLY_FAN_RUN := (StartDelayScans >= 1500);
    ELSE
        StartDelayScans := 0;
        SUPPLY_FAN_RUN := FALSE;
    END_IF;

    (* Temperature adjustment is independent of the fan delay. *)
    CASE HVAC_MODE_SELECTOR OF
        0:
            IF OCCUPANCY_DETECTED THEN
                TEMP_SETPOINT_ADJUST := 0;
            ELSIF ENERGY_SAVING_MODE THEN
                TEMP_SETPOINT_ADJUST := 3;
            ELSE
                TEMP_SETPOINT_ADJUST := 2;
            END_IF;

        1:
            IF OCCUPANCY_DETECTED THEN
                TEMP_SETPOINT_ADJUST := 0;
            ELSE
                TEMP_SETPOINT_ADJUST := 1;
            END_IF;

        2:
            IF OCCUPANCY_DETECTED THEN
                TEMP_SETPOINT_ADJUST := 0;
            ELSE
                TEMP_SETPOINT_ADJUST := 4;
            END_IF;

        3:
            TEMP_SETPOINT_ADJUST := 4;

        ELSE
            (* Outside the specified valid selector domain. *)
            TEMP_SETPOINT_ADJUST := 0;
    END_CASE;

    IF TEMP_SETPOINT_ADJUST > 4 THEN
        TEMP_SETPOINT_ADJUST := 4;
    ELSIF TEMP_SETPOINT_ADJUST < -4 THEN
        TEMP_SETPOINT_ADJUST := -4;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
